using V = std::vector<std::string>;

TEST("split on a delimiter") {
  CHECK(split("a,b,c", ',') == (V{"a", "b", "c"}));
  CHECK(split("one", ',') == (V{"one"}));
}

TEST("split keeps empty fields") {
  CHECK(split("a,,b", ',') == (V{"a", "", "b"}));
  CHECK(split("a,", ',') == (V{"a", ""}));
  CHECK(split(",a", ',') == (V{"", "a"}));
  CHECK(split("", ',') == (V{""}));
}

TEST("join") {
  CHECK_EQ(join({"a", "b", "c"}, ", "), std::string("a, b, c"));
  CHECK_EQ(join({"solo"}, "-"), std::string("solo"));
  CHECK_EQ(join({}, "-"), std::string(""));
}

TEST("join undoes split") {
  for (std::string s : {"a,b", ",,", "", "x,,y,"}) CHECK_EQ(join(split(s, ','), ","), s);
}

TEST("trim strips whitespace on both ends") {
  CHECK_EQ(trim("  hi there \t\r\n"), std::string_view("hi there"));
  CHECK_EQ(trim("   "), std::string_view(""));
  CHECK_EQ(trim(""), std::string_view(""));
  CHECK_EQ(trim("x"), std::string_view("x"));
}

TEST("trim returns a view into the original") {
  std::string s = "  abc  ";
  std::string_view t = trim(s);
  CHECK(t.data() == s.data() + 2);
  CHECK_EQ(t.size(), std::size_t{3});
}

TEST("to_lower and starts_with_ci") {
  CHECK_EQ(to_lower("Hello, WORLD 42"), std::string("hello, world 42"));
  CHECK(starts_with_ci("Content-Type: text", "content-type"));
  CHECK(!starts_with_ci("Con", "content"));
  CHECK(starts_with_ci("anything", ""));
}

