#include <cctype>
#include <string>
#include <string_view>
#include <vector>

std::vector<std::string> split(std::string_view s, char delim) {
  std::vector<std::string> out;
  std::size_t start = 0;
  while (true) {
    std::size_t end = s.find(delim, start);
    if (end == std::string_view::npos) {
      out.emplace_back(s.substr(start));  // the last field, possibly empty
      return out;
    }
    out.emplace_back(s.substr(start, end - start));
    start = end + 1;
  }
}

std::string join(const std::vector<std::string>& parts, std::string_view sep) {
  std::string out;
  for (std::size_t i = 0; i < parts.size(); ++i) {
    if (i > 0) out += sep;
    out += parts[i];
  }
  return out;
}

std::string_view trim(std::string_view s) {
  constexpr std::string_view ws = " \t\r\n";
  std::size_t first = s.find_first_not_of(ws);
  if (first == std::string_view::npos) return s.substr(s.size());  // all whitespace: empty view
  std::size_t last = s.find_last_not_of(ws);
  return s.substr(first, last - first + 1);  // substr on a view never copies
}

static char lower(char c) {
  // std::tolower takes an int that must be representable as unsigned char;
  // passing a negative char (any non-ASCII byte) is undefined behaviour.
  return static_cast<char>(std::tolower(static_cast<unsigned char>(c)));
}

std::string to_lower(std::string_view s) {
  std::string out(s);
  for (char& c : out) c = lower(c);
  return out;
}

bool starts_with_ci(std::string_view s, std::string_view prefix) {
  if (prefix.size() > s.size()) return false;
  for (std::size_t i = 0; i < prefix.size(); ++i)
    if (lower(s[i]) != lower(prefix[i])) return false;
  return true;
}
